// generate-getting-started.mjs — single-source the Getting Started guide from
// the canonical docs/operations/onboarding.md so the website cannot drift.
// Mirrors the generate-gateway-api-docs.ts pattern: generated file is committed
// and regenerated on every docs start/build.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const source = resolve(repoRoot, 'docs', 'operations', 'onboarding.md');
const target = resolve(repoRoot, 'apps', 'docs', 'docs', 'guides', 'getting-started.generated.md');

const body = readFileSync(source, 'utf-8')
  // Repo-relative links don't resolve on the website — point at the repo. Target the
  // link URL (`](...)`) so the display text is left intact.
  .replaceAll(
    '../reference/project-packs.md',
    'https://github.com/deeeed/farmslot/blob/main/docs/reference/project-packs.md',
  )
  .replaceAll(
    '](onboarding-flow.md)',
    '](https://github.com/deeeed/farmslot/blob/main/docs/operations/onboarding-flow.md)',
  );

// Do-not-edit notice lives in YAML frontmatter comments: MDX comments in the
// body get mangled by the repo prettier pass ({/* */} -> {/_ _/}).
// The hero block makes the one-line installer the first thing readers see;
// Docusaurus code blocks ship a copy button out of the box.
const header = `---
# GENERATED FILE — do not edit. Source of truth: docs/operations/onboarding.md.
# Regenerated by apps/docs/scripts/generate-getting-started.mjs on docs start/build.
title: Getting started — install Farmslot
sidebar_label: Getting started
slug: /guides/getting-started
---

:::tip Install with one command

\`\`\`bash
curl -fsSL https://raw.githubusercontent.com/deeeed/farmslot/main/install.sh | bash
\`\`\`

Copy, paste, done — prerequisites are checked (never auto-installed), a
workspace lands in \`~/farmslot/\`, and the run ends with a green
\`farmslot doctor\`. Early preview: \`main\` moves daily, run \`farmslot update\`
often.

:::

`;

// Drop the source's own H1 (frontmatter title replaces it).
const withoutH1 = body.replace(/^# .*\n/, '');
writeFileSync(target, header + withoutH1);
console.log(`generated ${target} from ${source}`);
